#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-or-later
# Copyright (C) 2025 Matias Pacheco-Alarcon <matias.pacheco.a@gmail.com>
#
# Safety net of the readability refactor (Phase 9, D-020): the Fortran generated by fypp must not
# change when a template is rewritten by hand.
#
#   tools/gen_snapshot.sh save    [BUILD_DIR] [SNAP_DIR]   store the normalized generated sources
#   tools/gen_snapshot.sh compare [BUILD_DIR] [SNAP_DIR]   compare the current build with the snapshot
#
# BUILD_DIR defaults to build-check and SNAP_DIR to build-snapshots/<BUILD_DIR name>. The library
# target `muscle` is rebuilt first. Normalization joins continued statements, drops `#line` markers, comments, blank lines and
# the case and spacing of the code, and split `public`, `module procedure` and `use, only` lists into
# one name per line, so only real changes in the code show up.
# - Same normalized text: identical.
# - Same lines in another order (declarations moved): "reordered", to be read by hand.
# - Anything else: "changed", with the diff.
# The public symbol table of the library (nm, defined symbols) is compared as well.
# Exit status != 0 if something changed (reordered counts as changed unless --allow-reorder).

set -u
cd "$(dirname "$0")/.."

allow_reorder=0
if [[ "${1:-}" == --allow-reorder ]]; then allow_reorder=1; shift; fi
mode="${1:-}"
build_dir="${2:-build-check}"
snap_dir="${3:-build-snapshots/$(basename "$build_dir")}"
case "$mode" in save|compare) ;; *)
    echo "usage: $0 [--allow-reorder] save|compare [BUILD_DIR] [SNAP_DIR]" >&2; exit 2 ;;
esac

cmake --build "$build_dir" --target muscle -j8 > /dev/null || { echo "build of target muscle failed" >&2; exit 2; }
gen_root="$build_dir/fypp"

# normalize <file>: code only, one statement piece per line.
normalize() {
    perl -0pe '
        s/^#line.*\n//mg;
        s/&[ \t]*\n(?:[ \t]*(?:!.*)?\n)*[ \t]*&?/ /g;   # continuation lines: one statement per line
    ' "$1" | perl -ne '
        next if /^#line/;
        s/^\s*!.*$//;                 # comment lines
        s/\s+!(?![^\x27"]*[\x27"]).*$//;  # trailing comments outside strings
        s/\s+/ /g; s/^ //; s/ $//;
        next if $_ eq "" or $_ eq "\n";
        $_ = lc($_);
        # name lists (public, module procedure, use ..., only): one name per line
        if (/^(public ::|module procedure|use \w+, only :) (.*)$/) {
            my ($h, $l) = ($1, $2);
            print "$h $_\n" for split /\s*,\s*/, $l;
            next;
        }
        print $_, "\n";
    ' | sed '/^$/d'
}

symbols() {
    nm --defined-only "$build_dir/src/libmuscle.a" 2> /dev/null | awk 'NF==3 {print $2, $3}' | sort -u
}

if [[ "$mode" == save ]]; then
    rm -rf "$snap_dir"; mkdir -p "$snap_dir/code"
    n=0
    while IFS= read -r f; do
        rel="${f#"$gen_root"/}"; mkdir -p "$snap_dir/code/$(dirname "$rel")"
        normalize "$f" > "$snap_dir/code/$rel"; n=$((n + 1))
    done < <(find "$gen_root/src" -name '*.f90' | sort)
    symbols > "$snap_dir/symbols.txt"
    echo "snapshot: $n files, $(wc -l < "$snap_dir/symbols.txt") symbols -> $snap_dir"
    exit 0
fi

[[ -d "$snap_dir/code" ]] || { echo "no snapshot in $snap_dir (run save first)" >&2; exit 2; }
same=0; reordered=0; changed=0; added=0; removed=0
tmp="$(mktemp)"; trap 'rm -f "$tmp"' EXIT
while IFS= read -r f; do
    rel="${f#"$gen_root"/}"; old="$snap_dir/code/$rel"
    if [[ ! -f "$old" ]]; then echo "ADDED    $rel"; added=$((added + 1)); continue; fi
    normalize "$f" > "$tmp"
    if cmp -s "$old" "$tmp"; then same=$((same + 1))
    elif diff -q <(sort "$old") <(sort "$tmp") > /dev/null; then
        echo "REORDERED $rel"; reordered=$((reordered + 1))
    else
        echo "CHANGED  $rel"; diff <(sort "$old") <(sort "$tmp") | head -20 | sed 's/^/    /'
        changed=$((changed + 1))
    fi
done < <(find "$gen_root/src" -name '*.f90' | sort)
while IFS= read -r old; do
    rel="${old#"$snap_dir"/code/}"
    [[ -f "$gen_root/$rel" ]] || { echo "REMOVED  $rel"; removed=$((removed + 1)); }
done < <(find "$snap_dir/code" -type f | sort)

sym_status="identical"
if ! diff -u "$snap_dir/symbols.txt" <(symbols) > "$tmp.sym"; then
    sym_status="DIFFERENT"; sed 's/^/    /' "$tmp.sym" | head -40
fi
rm -f "$tmp.sym"
echo "files: $same identical, $reordered reordered, $changed changed, $added added, $removed removed; symbols: $sym_status"
status=0
(( changed + added + removed > 0 )) && status=1
[[ "$sym_status" != identical ]] && status=1
(( reordered > 0 && allow_reorder == 0 )) && status=1
exit $status
